document.addEventListener("DOMContentLoaded", () => {
  const grid = document.getElementById("grid-productos");
  const buscador = document.getElementById("buscador");
  const categoriasNav = document.getElementById("categorias-nav");
  const subcategoriasNav = document.getElementById("subcategorias-nav");

  if (!grid) return;

  let productos = [];
  let catalogo = null;
  let categoriaActiva = null;
  let subcategoriaActiva = null;

  const escapeHtml = (value = "") =>
    String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;")
      .replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");

  const imagePath = (p) => p.imagen ? `img/${p.imagen}` : (p.imagen_url || "img/placeholder.png");

  function render(products) {
    grid.innerHTML = "";
    if (!products.length) {
      grid.innerHTML = '<div class="col-12"><p class="text-center text-muted">No se encontraron productos.</p></div>';
      return;
    }
    products.forEach((p) => {
      const col = document.createElement("div");
      col.className = "col mb-5";
      col.innerHTML = `
        <div class="card h-100 shadow-sm">
          <img class="card-img-top" loading="lazy" src="${escapeHtml(imagePath(p))}"
            alt="${escapeHtml(p.nombre || "Producto Relive")}"
            style="object-fit:contain;width:100%;height:220px;padding:12px;"
            onerror="this.onerror=null;this.src='img/placeholder.png';" />
          <div class="card-body p-4">
            <div class="text-center">
              <small class="text-muted">${escapeHtml(p.categoria || "")} · ${escapeHtml(p.subcategoria || "")}</small>
              <h5 class="fw-bolder mt-2">${escapeHtml(p.nombre || "Producto")}</h5>
              ${p.descripcion ? `<p class="small text-muted mb-2">${escapeHtml(p.descripcion)}</p>` : ""}
              ${p.marca ? `<div class="small text-muted">Marca: ${escapeHtml(p.marca)}</div>` : ""}
              ${p.codigo ? `<div class="small text-muted">Código: ${escapeHtml(p.codigo)}</div>` : ""}
              ${p.precio != null ? `<div class="mt-2 text-success fw-bold">$${Number(p.precio).toFixed(0)}</div>` : ""}
            </div>
          </div>
        </div>`;
      grid.appendChild(col);
    });
  }

  function filtrar() {
    const q = (buscador?.value || "").trim().toLowerCase();
    const filtrados = productos.filter((p) => {
      const coincideCategoria = !categoriaActiva || p.categoria === categoriaActiva;
      const coincideSub = !subcategoriaActiva || p.subcategoria === subcategoriaActiva;
      const texto = [p.nombre,p.descripcion,p.codigo,p.marca,p.categoria,p.subcategoria].filter(Boolean).join(" ").toLowerCase();
      return coincideCategoria && coincideSub && (!q || texto.includes(q));
    });
    render(filtrados);
  }

  function boton(texto, activo, onClick) {
    const b = document.createElement("button");
    b.type = "button";
    b.className = activo ? "btn btn-dark" : "btn btn-outline-dark";
    b.textContent = texto;
    b.addEventListener("click", onClick);
    return b;
  }

  function renderCategorias() {
    if (!categoriasNav || !catalogo) return;
    categoriasNav.innerHTML = "";
    categoriasNav.appendChild(boton("Todas", !categoriaActiva, () => {
      categoriaActiva = null;
      subcategoriaActiva = null;
      renderCategorias();
      filtrar();
    }));
    catalogo.categorias.forEach((cat) => {
      categoriasNav.appendChild(boton(`${cat.nombre} (${cat.cantidad_productos})`, categoriaActiva === cat.nombre, () => {
        categoriaActiva = cat.nombre;
        subcategoriaActiva = null;
        renderCategorias();
        renderSubcategorias();
        filtrar();
      }));
    });
    renderSubcategorias();
  }

  function renderSubcategorias() {
    if (!subcategoriasNav || !catalogo) return;
    subcategoriasNav.innerHTML = "";
    if (!categoriaActiva) return;
    const cat = catalogo.categorias.find(c => c.nombre === categoriaActiva);
    if (!cat) return;
    subcategoriasNav.appendChild(boton("Todas las subcategorías", !subcategoriaActiva, () => {
      subcategoriaActiva = null;
      renderSubcategorias();
      filtrar();
    }));
    cat.subcategorias.forEach((sub) => {
      subcategoriasNav.appendChild(boton(`${sub.nombre} (${sub.cantidad_productos})`, subcategoriaActiva === sub.nombre, () => {
        subcategoriaActiva = sub.nombre;
        renderSubcategorias();
        filtrar();
      }));
    });
  }

  fetch("productos_relive.json")
    .then((response) => {
      if (!response.ok) throw new Error(`No se pudo cargar productos_relive.json (HTTP ${response.status})`);
      return response.json();
    })
    .then((data) => {
      catalogo = data;
      productos = Array.isArray(data) ? data : (data.productos || []);
      renderCategorias();
      render(productos);
      if (buscador) buscador.addEventListener("input", filtrar);
    })
    .catch((error) => {
      console.error(error);
      grid.innerHTML = '<div class="col-12"><p class="text-center text-muted">No se pudo cargar el catálogo.</p></div>';
    });
});